styles.css:
&{--ls-tick-phase-pad:var(--wp--preset--spacing--30);--ls-tick-phase-offset:0.2em;list-style:none;margin:0;padding:0;}
& li{position:relative;padding-block:var(--ls-tick-phase-pad);padding-inline-start:calc(1.375rem + var(--wp--preset--spacing--20));border-block-end:1px solid var(--wp--custom--color--border--card);}
& li:last-child{border-block-end:0;}
& strong{font-weight:var(--wp--custom--typography--font-weight--bold);}
&.ls-tick-phase--compact{--ls-tick-phase-pad:var(--wp--preset--spacing--20);--ls-tick-phase-offset:0.05rem;}
&.ls-tick-phase--on-dark{--ls-tick-phase-accent:var(--ls-phase-accent-on-dark);}
&.ls-tick-phase--on-dark li{border-block-end-color:color-mix(in srgb, var(--wp--custom--color--text--on-dark) 16%, transparent);}
